local DreamlandUtils = {}

---GetDreamlandQuestVo 梦境空间关卡表
function DreamlandUtils.GetDreamlandQuestVo(id)
    if checkNumber(id) == 0 then
        return nil
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3080, "DreamlandQuestVo", id)
    return vo
end


---DreamlandTalksVo 梦境空间对白表
function DreamlandUtils.GetDreamlandTalksVo( StoryId )
    if checkNumber(StoryId) == 0 then
        return nil
    end
    local t = {}
    local vos = CfUtils.GetCf(AutoIds.IdSetting3084, "DreamlandTalksVo", true)
    for i, vo in ipairs(vos) do
        if vo.StoryId == StoryId then
            table.insert(t, vo)
        end
    end
    return t
end



---GetDreamlandQuestRewardVo 梦境空间关卡奖励表
function DreamlandUtils.GetDreamlandQuestRewardVo(questId_)
    if checkNumber(questId_) == 0 then
        return nil
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3081, "DreamlandQuestRewardVo", questId_)
    return vo
end

