---GetDreamlandCollectionVo 梦境空间碎片收集进度表
function DreamlandUtils.GetAllDreamlandCollectionVoByQuestId(questId_)
    if checkNumber(questId_) == 0 then
        printError("koko 参数 questId 异常")
        return nil
    end

    local ret = {}
    local vos = CfUtils.GetCf(AutoIds.IdSetting3083, "DreamlandCollectionVo", true)
    for i, vo in ipairs(vos) do
        if isNotNull(vo) and vo.levelId == questId_ then
            ret[vo.pieceId] = { 
                isGot = (vo.isGot==1) and true or false,
                id = vo.id
            }
        end
    end
    ---
    if table.count(ret) == 0 then 
        printError( "koko 配表异常, 没找到 碎片信息: " .. tostring(questId_) )
    end
    return ret
end


-- 得到配表中, 本关卡的所有碎片的数量: 
function DreamlandUtils.GetAllPiecesNumByQuestId(questId_)
    local vos = DreamlandUtils.GetAllDreamlandCollectionVoByQuestId(questId_) -- 一定得到一个 table array
    return table.count( vos )
end


function DreamlandUtils.IsUnlock(id)
    local vo = DreamlandUtils.GetDreamlandQuestVo(id)
    local isUnlock = GameUtils.IsUnlockedSingle(Constants.CommonUnlockType.PassQuest, vo.unlockNum)
    local err = GameUtils.GetUnlockDescr(Constants.CommonUnlockType.PassQuest, vo.unlockNum)

    return true, err
end


--获取一个关卡数据   "OverseaBoxQuest/home.data.boxQuestInfo[questId_]", 可能得到 nil
-- id: levelID, questId
function DreamlandUtils.GetHomeDojoBoxQuestInfo(questId_)
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DreamlandComponent)
    local t = comp:GetQuestInfo()

    return t[checkString(questId_)]
end


-- "OverseaBoxQuest/home.data.boxQuestInfo[questId_]" 中, 所有有效的 piece 信息 (是个数组)
-- id: levelID, questId
function DreamlandUtils.GetHomeDojoPieces(questId_)
    local t = DreamlandUtils.GetHomeDojoBoxQuestInfo(questId_)
    local ret = {}
    if not t then
        print("koko 配表数据 boxQuestInfo 为空, 但有时这是正常的")
        return ret
    end
    -- 剔除潜在的 异常元素, 比如 ""
    for k,p in pairs(t.piece) do 
        if type(p)=="string" and #p>0  then 
            if #p>0 then 
                table.insert( ret, p )
            else 
                printError( "后端参数异常" )
            end 
        end 
    end
    ---
    return ret
end



return DreamlandUtils
